old="""$('pupilForm').addEventListener('submit',async e=>{e.preventDefault();const row={user_id:user.id,full_name:$('pupilName').value.trim(),class_name:$('pupilClass').value.trim(),guardian_phone:$('guardianPhone').value.trim()||null,admission_number:$('pupilAdmissionNo').value.trim()||null,date_of_birth:$('pupilDob').value||null,guardian_name:$('pupilGuardianName').value.trim()||null,guardian_email:$('pupilGuardianEmail').value.trim()||null,home_address:$('pupilAddress').value.trim()||null,emergency_contact_name:$('pupilEmergencyName').value.trim()||null,emergency_contact_phone:$('pupilEmergencyPhone').value.trim()||null,welfare_notes:$('pupilWelfareNotes').value.trim()||null,amount_paid:Number($('pupilAmountPaid').value||0),payment_status:$('pupilPaymentStatus').value,enrollment_date:$('pupilEnrollmentDate').value,term:$('pupilTerm').value,school_year:Number($('pupilYear').value),pupil_type:$('pupilType').value,requirements_checklist:$('pupilType').value==='NEW'?Array.from(document.querySelectorAll('.new-pupil-requirement:checked')).map(el=>el.value):[]};const {error}=await sb.from('pupils').insert(row);if(error){appAlert('Pupil could not be saved: '+error.message);return}e.target.reset();document.querySelectorAll('.new-pupil-requirement').forEach(el=>el.checked=false);$('pupilEnrollmentDate').value=today;await loadRecords();toast('Pupil saved')});"""
new="""$('pupilForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button[type=submit],button:not([type])');if(button){button.disabled=true;button.dataset.originalText=button.textContent;button.textContent='SAVING…'}try{const row={user_id:user.id,full_name:$('pupilName').value.trim(),class_name:$('pupilClass').value.trim(),guardian_phone:$('guardianPhone').value.trim()||null,admission_number:$('pupilAdmissionNo').value.trim()||null,date_of_birth:$('pupilDob').value||null,guardian_name:$('pupilGuardianName').value.trim()||null,guardian_email:$('pupilGuardianEmail').value.trim()||null,home_address:$('pupilAddress').value.trim()||null,emergency_contact_name:$('pupilEmergencyName').value.trim()||null,emergency_contact_phone:$('pupilEmergencyPhone').value.trim()||null,welfare_notes:$('pupilWelfareNotes').value.trim()||null,amount_paid:Number($('pupilAmountPaid').value||0),payment_status:$('pupilPaymentStatus').value,enrollment_date:$('pupilEnrollmentDate').value,term:$('pupilTerm').value,school_year:Number($('pupilYear').value),pupil_type:$('pupilType').value,requirements_checklist:$('pupilType').value==='NEW'?Array.from(document.querySelectorAll('.new-pupil-requirement:checked')).map(el=>el.value):[]};const {error}=await sb.from('pupils').insert(row);if(error){appAlert('Pupil could not be saved. Your entries have been kept. '+error.message);return}toast('Pupil saved');form.reset();document.querySelectorAll('.new-pupil-requirement').forEach(el=>el.checked=false);$('pupilEnrollmentDate').value=today;$('pupilYear').value=new Date().getFullYear();await loadRecords()}catch(err){appAlert('Pupil could not be saved. Your entries have been kept. '+(err?.message||String(err)))}finally{if(button){button.disabled=false;button.textContent=button.dataset.originalText||'Save pupil'}}});"""
