old2="""$('gradeFeeForm').addEventListener('submit',async e=>{e.preventDefault();const grade=$('feeGrade').value.trim(),amount=Number($('feeAmount').value);if(!grade||amount<0)return;const existing=gradeFees.find(f=>String(f.grade_name).toLowerCase()===grade.toLowerCase());const result=existing?await sb.from('school_grade_fees').update({fee_amount:amount}).eq('id',existing.id).eq('user_id',user.id):await sb.from('school_grade_fees').insert({user_id:user.id,grade_name:grade,fee_amount:amount});if(result.error){appAlert('Grade fees could not be saved. Run the included SQL migration first. '+result.error.message);return}e.target.reset();await loadRecords();toast('Grade fees saved')});"""
new2="""$('gradeFeeForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button[type=submit],button:not([type])'),grade=$('feeGrade').value.trim(),amount=Number($('feeAmount').value);if(!grade||!Number.isFinite(amount)||amount<0){appAlert('Choose a grade and enter a valid fee amount.');return}if(button){button.disabled=true;button.dataset.originalText=button.textContent;button.textContent='SAVING…'}try{const existing=gradeFees.find(f=>String(f.grade_name).toLowerCase()===grade.toLowerCase());const result=existing?await sb.from('school_grade_fees').update({fee_amount:amount}).eq('id',existing.id).eq('user_id',user.id):await sb.from('school_grade_fees').insert({user_id:user.id,grade_name:grade,fee_amount:amount});if(result.error){appAlert('Grade fees could not be saved. Your entries have been kept. '+result.error.message);return}toast('Grade fees saved');form.reset();await loadRecords()}catch(err){appAlert('Grade fees could not be saved. Your entries have been kept. '+(err?.message||String(err)))}finally{if(button){button.disabled=false;button.textContent=button.dataset.originalText||'SAVE GRADE FEES'}}});"""
