# set year default when page starts; attach near date default assignment
s=s.replace("$('pupilEnrollmentDate').value=today;", "$('pupilEnrollmentDate').value=today;if($('pupilYear')&&!$('pupilYear').value)$('pupilYear').value=new Date().getFullYear();", 1)
