# add migration
m=Path('/tmp/gcfix/SUPABASE_MIGRATION.sql')
t=m.read_text()
if 'school_year' not in t:
    t += "\n-- Pupil academic year used alongside term in the Add Pupil form.\nALTER TABLE public.pupils ADD COLUMN IF NOT EXISTS school_year integer NOT NULL DEFAULT EXTRACT(YEAR FROM CURRENT_DATE)::integer;\n"
m.write_text(t)
# also update readme with required migration note
r=Path('/tmp/gcfix/README.txt')
if r.exists():
    txt=r.read_text(errors='ignore')
    txt += "\n\nPUPIL YEAR FIELD: The updated Add Pupil form saves school_year. Run the updated SUPABASE_MIGRATION.sql in the Supabase SQL Editor before deploying this version. The pupil and grade-fee forms now retain entered values when Supabase returns an error and only clear after a successful save.\n"
    r.write_text(txt)
